def resolve_asr_model(
    env: Optional[Mapping[str, str]] = None, cwd: Optional[Path] = None, root: Optional[Path] = None
) -> Tuple[str, List[str]]:
    """(folder or repo id to pass to from_pretrained, the local folders that were checked)."""
    env = os.environ if env is None else env
    explicit = env.get("QP_ASR_MODEL", "").strip()
    if explicit:
        path = Path(explicit).expanduser()
        if path.is_dir():
            return str(path), [str(path)]
        if "/" in explicit and not path.is_absolute() and not explicit.startswith((".", "~")):
            return explicit, []  # a Hugging Face repo id such as org/name
        raise FileNotFoundError(
            f"QP_ASR_MODEL={explicit!r} is neither an existing folder nor a Hugging Face repo id ('organisation/name')."
        )
    tried: List[str] = []
    for base in (cwd or Path.cwd(), root or _repository_root()):
        if base is None:
            continue
        folder = Path(base) / ASR_FOLDER_NAME
        tried.append(str(folder))
        if (folder / "config.json").is_file():
            return str(folder), tried
    return ASR_REPO_ID, tried

def get_user_by_email(self, email: str) -> Optional[Dict[str, Any]]:
    """Returns user record WITHOUT password_hash for safety."""
    try:
        with self._connection() as con:
            row = con.execute(
                "SELECT user_id, username, email, created_at FROM users WHERE LOWER(email) = ?",
                (self.normalize_email(email),),
            ).fetchone()
        return dict(row) if row else None
    except Exception as e:
        self.logger.error(f"get_user_by_email failed: {e}")
        return None

def _email_taken(self, con, email: str, except_user_id: Optional[str] = None) -> bool:
    # LOWER() also catches legacy rows that were stored with capitals.
    row = con.execute(
        "SELECT user_id FROM users WHERE LOWER(email) = ?", (email,)
    ).fetchone()
    return bool(row) and row["user_id"] != except_user_id

def update_user_email(self, user_id: str, new_email: str) -> bool:
    new_email = self.normalize_email(new_email)
    try:
        with self._connection() as con:
            if self._email_taken(con, new_email, except_user_id=user_id):
                self.logger.error(f"Email {new_email} is already in use.")
                return False
            cur = con.execute(
                "UPDATE users SET email = ? WHERE user_id = ?", (new_email, user_id)
            )
            return cur.rowcount > 0
    except sqlite3.IntegrityError:
        self.logger.error(f"Email {new_email} is already in use.")
        return False
    except Exception as e:
        self.logger.error(f"Failed to update user {user_id}: {e}")
        return False

