while True:
    q = self.session.ctx.current_question
    self._show_question(q)

    try:
        if RICH_AVAILABLE:
            answer = Prompt.ask(
                "  [bold]Your answer[/]  [dim](or 'skip' / 'quit')[/]"
            ).strip()
        else:
            answer = input("  Your answer (or 'skip' / 'quit'): ").strip()
    except (KeyboardInterrupt, EOFError):
        self._p("\n[dim]Interrupted.[/]")
        break

    cmd = answer.lower()
    if cmd in ("quit", "q", "exit"):
        self._p("[dim]Ending session early.[/]")
        break

    if cmd in ("skip", "s", ""):
        self._p("[dim]Skipped.[/]")
        nxt = self.session.logic.select_next_question(
            self.session.ctx.difficulty_label, self.session.used_ids
        )
        if not nxt:
            break
        self.session.ctx.current_question = nxt
        self.session.used_ids.add(nxt.id)
        continue

    chroma_hits: List[Dict] = []
    if self.debug and self.chroma and self.chroma.ready:
        chroma_hits = self.chroma.query(answer, n=3)

    result_dict = self.session.evaluate_turn(answer)
    if "error" in result_dict:
        self._p(f"[red]{result_dict['error']}[/]")
        break

    tr = self.session.ctx.history[-1]
    self._show_feedback(tr, q, chroma_hits)

    if result_dict["is_terminal"]:
        self._rule()
        self._p("\n[bold green]  All questions answered — great work![/]\n")
        break

self._rule("End of Session")
self._summary()

def load_secret(data_dir: Path) -> bytes:
    env = os.environ.get("QP_JWT_SECRET", "").strip()
    if env:
        return env.encode("utf-8")

    secret_file = Path(data_dir) / ".jwt_secret"
    if secret_file.exists():
        existing = secret_file.read_text().strip()
        if existing:
            return existing.encode("utf-8")

    generated = secrets.token_urlsafe(48)
    fd = os.open(str(secret_file), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w") as fh:
        fh.write(generated)
    return generated.encode("utf-8")

@app.post("/api/files/ingest")
@limiter.limit("5/minute")
async def ingest_file(
    request: Request,
    background_tasks: BackgroundTasks,
    current_user: CurrentUser,
    file: UploadFile = File(...),
):
    # .name strips any directory components the client put in the filename.
    safe_name = Path(file.filename or "upload.pdf").name

    head = await file.read(5)
    if head != b"%PDF-":
        raise HTTPException(400, "Only PDF files are accepted.")

    temp_path = DATA_DIR / f"{uuid.uuid4()}_{safe_name}"
    digest = hashlib.sha256(head)
    size = len(head)
    try:
        with open(temp_path, "wb") as f:
            f.write(head)
            while chunk := await file.read(UPLOAD_CHUNK_BYTES):
                size += len(chunk)
                if size > MAX_UPLOAD_BYTES:
                    raise HTTPException(
                        413,
                        f"File too large (limit {MAX_UPLOAD_BYTES // (1024 * 1024)} MB).",
                    )
                digest.update(chunk)
                await run_in_threadpool(f.write, chunk)
    except BaseException:
        temp_path.unlink(missing_ok=True)
        raise
    sha256 = digest.hexdigest()

    # Exact re-upload by the same user: answer immediately, before any Docling work.
    existing = await run_in_threadpool(db.get_file_by_sha256_for_user, current_user, sha256)
    if existing or (current_user, sha256) in _ingesting:
        temp_path.unlink(missing_ok=True)
        if existing:
            return JSONResponse(
                {
                    "detail": f"You already uploaded this file as “{existing['file_name']}”.",
                    "file_id": existing["file_id"],
                    "file_name": existing["file_name"],
                },
                status_code=409,
            )
        return JSONResponse(
            {"detail": "This file is already being processed."}, status_code=409
        )

    _ingesting.add((current_user, sha256))
    background_tasks.add_task(run_ingestion_task, temp_path, current_user, sha256)
    return {
        "status": "processing",
        "message": "File uploaded. Ingestion running in background.",
        "filename": safe_name,
    }

