@dataclass
class Report:
    orphan_ids: List[str] = field(default_factory=list)  # Chroma ids to delete
    orphan_file_ids: Set[str] = field(default_factory=set)  # file_ids (or "" if metadata is missing)
    unindexed_file_ids: List[str] = field(default_factory=list)
    chroma_total: int = 0
    pending_deletions: List[str] = field(default_factory=list)

    @property
    def clean(self) -> bool:
        return not self.orphan_ids and not self.unindexed_file_ids

def compare(collection, db_path: str) -> Report:
    all_files, with_questions, pending = sqlite_state(db_path)
    docs = chroma_file_ids(collection)

    report = Report(chroma_total=len(docs), pending_deletions=sorted(pending))
    for cid, fid in sorted(docs.items()):
        if fid not in all_files:
            report.orphan_ids.append(cid)
            report.orphan_file_ids.add(fid)
    indexed = {fid for fid in docs.values() if fid}
    report.unindexed_file_ids = sorted(with_questions - indexed)
    return report

def delete_orphans(collection, report: Report) -> int:
    for i in range(0, len(report.orphan_ids), _PAGE):
        collection.delete(ids=report.orphan_ids[i : i + _PAGE])
    return len(report.orphan_ids)

def difficulty_instructions(self, content_type: str) -> Dict[str, str]:
    if content_type == "math":
        return {
            "Easy": "definition or notation — ask what a symbol, term, or operator means",
            "Medium": "computation — ask what the formula computes or what its components represent",
            "Hard": "derivation or proof — ask why the formula takes this form, what assumption it relies on, or what happens if a constraint is relaxed",
        }
    return {
        "Easy": "factual recall — ask about specific definitions, names, or stated facts",
        "Medium": "conceptual / mechanism — ask how or why something works",
        "Hard": "analytical / critical — ask about limitations, trade-offs, or comparisons",
    }

def _is_useful_table(self, text: str, metadata: Dict[str, Any]) -> bool:
    lines = text.split("\n")
    table_rows = sum(1 for line in lines if "|" in line)
    header = (metadata.get("section_header") or "").lower()
    if any(x in header for x in ["table of contents", "contents"]):
        return False
    if table_rows > 5 and len(lines) > 0 and (table_rows / len(lines)) > 0.4:
        return True
    return False

def evaluate_chunk(self, content: str, metadata: Dict[str, Any]) -> Dict[str, Any]:
    text = (content or "").strip()
    text_lower = text.lower()

    if len(text) < 30 or not text_lower:
        return self._result(False, "Too short/Empty", "noise", 0)

    header_text = ""
    for key in ("section_header", "Header 3", "Header 2", "Header 1"):
        val = metadata.get(key)
        if val:
            header_text = str(val).lower()
            break

    if any(exclude in header_text for exclude in self.metadata_excludes):
        return self._result(False, f"Header filter: {header_text}", "metadata", 0)

    if any(text_lower.startswith(ex) for ex in self.content_prefix_excludes):
        return self._result(False, "Forbidden prefix", "other", 0)

    if len(text) < 150:
        if self.patterns["url"].search(text_lower) or self.patterns["doi"].search(
            text_lower
        ):
            return self._result(False, "Citation/Link chunk", "metadata", 0)

    if any(ex in text_lower[:400] for ex in self.content_anywhere_excludes):
        return self._result(False, "Metadata keyword detected", "metadata", 0)

    if self._is_table_of_contents(text):
        return self._result(False, "Detected Table of Contents", "toc", 0)

    alpha_ratio = self._alpha_ratio(text)

    if self.patterns["code_block"].search(text):
        return self._result(True, "Source code block", "code", 85)

    if alpha_ratio < 0.30:
        if self._is_useful_table(text, metadata):
            return self._result(True, "Useful data table", "table", 75)
        return self._result(False, f"Low alpha ({alpha_ratio:.2%})", "metadata", 20)

    quality_score = self._calculate_quality_score(text, metadata, alpha_ratio)
    return self._result(True, "OK", "main_content", quality_score)

