def chroma_file_ids(collection) -> Dict[str, str]:
    """{chroma id: file_id ('' when the metadata has none)} for every document."""
    out: Dict[str, str] = {}
    offset = 0
    while True:
        page = collection.get(include=["metadatas"], limit=_PAGE, offset=offset)
        ids = page.get("ids") or []
        if not ids:
            return out
        for cid, meta in zip(ids, page.get("metadatas") or [{}] * len(ids)):
            out[cid] = str((meta or {}).get("file_id") or "")
        offset += len(ids)

def get_simhashes_for_user(self, user_id: str) -> Dict[str, str]:
    """{simhash: file_id} for the files assigned to one user (per-user duplicate scope)."""
    sql = """
        SELECT f.simhash, f.file_id
        FROM files f
        JOIN user_files uf ON uf.file_id = f.file_id
        WHERE uf.user_id = ? AND f.simhash IS NOT NULL
    """
    try:
        with self._connection() as con:
            rows = con.execute(sql, (user_id,)).fetchall()
            return {row["simhash"]: row["file_id"] for row in rows}
    except Exception as e:
        self.logger.error(f"Failed to fetch simhashes for user: {e}")
        return {}

