def get_simhashes_for_user(self, user_id: str) -> Dict[str, str]:
    """{simhash: file_id} for the files assigned to one user (per-user duplicate scope)."""
    sql = """
        SELECT f.simhash, f.file_id
        FROM files f
        JOIN user_files uf ON uf.file_id = f.file_id
        WHERE uf.user_id = ? AND f.simhash IS NOT NULL
    """
    try:
        with self._connection() as con:
            rows = con.execute(sql, (user_id,)).fetchall()
            return {row["simhash"]: row["file_id"] for row in rows}
    except Exception as e:
        self.logger.error(f"Failed to fetch simhashes for user: {e}")
        return {}

def find_similar_questions(
    self,
    question_text: str,
    top_k: int = 5,
    min_similarity: float = 0.80,
) -> List[Dict[str, Any]]:
    query_vec = self._embed(question_text)

    results = self.collection.query(
        query_embeddings=[query_vec],
        n_results=top_k,
        # Filter to only match against questions, not answers
        where={"type": "question"},
    )

    filtered = []
    if results["ids"]:
        for i in range(len(results["ids"][0])):
            dist = results["distances"][0][i]
            # If using cosine distance: Similarity = 1 - Distance
            similarity = 1.0 - dist

            if similarity >= min_similarity:
                filtered.append(
                    {
                        "id": results["ids"][0][i],
                        "question": results["documents"][0][i],
                        "metadata": results["metadatas"][0][i],
                        "similarity": round(similarity, 3),
                    }
                )

    return filtered

